// Enterprise-grade task dispatcher
const currentTime = new Date();
const hour = currentTime.getHours();
const minute = currentTime.getMinutes();

// Smart scheduling based on time and load
const tasks = [];

// System monitoring every 10 minutes
if (minute % 10 === 0) {
  tasks.push('system_health_check');
}

// Data ingestion every 6 hours
if (hour % 6 === 0 && minute === 0) {
  tasks.push('multi_source_ingestion');
}

// Alert processing every 5 minutes
if (minute % 5 === 0) {
  tasks.push('alert_management');
}

// Portfolio analysis every 12 hours
if (hour % 12 === 0 && minute === 0) {
  tasks.push('portfolio_analysis');
}

// ML model management every 12 hours (offset by 6 hours)
if (hour % 12 === 6 && minute === 0) {
  tasks.push('ml_model_management');
}

// External API sync every 4 hours
if (hour % 4 === 0 && minute === 0) {
  tasks.push('external_api_integration');
}

// Data cleanup daily at 2 AM
if (hour === 2 && minute === 0) {
  tasks.push('data_cleanup');
}

return tasks.map(task => ({ json: { task_name: task, scheduled_time: currentTime.toISOString(), priority: getPriority(task) } }));

function getPriority(task) {
  const priorities = {
    'system_health_check': 'high',
    'alert_management': 'critical',
    'multi_source_ingestion': 'high',
    'portfolio_analysis': 'medium',
    'ml_model_management': 'medium',
    'external_api_integration': 'medium',
    'data_cleanup': 'low'
  };
  return priorities[task] || 'medium';
}

return items.sort((a, b) => {
  const priorityOrder = { 'critical': 3, 'high': 2, 'medium': 1, 'low': 0 };
  return priorityOrder[b.json.priority] - priorityOrder[a.json.priority];
});

// Enterprise-grade error handler
const error = $json.error || 'Unknown error';
const taskName = $json.task_name || 'Unknown task';
const timestamp = new Date().toISOString();

// Determine error severity
const isCritical = isCriticalError(error, taskName);
const shouldRetry = shouldRetryError(error, taskName);
const shouldEscalate = isCritical && !shouldRetry;

return [{
  json: {
    error_message: error,
    task_name: taskName,
    timestamp: timestamp,
    severity: isCritical ? 'critical' : 'warning',
    should_retry: shouldRetry,
    should_escalate: shouldEscalate,
    retry_count: ($json.retry_count || 0) + 1,
    max_retries: getMaxRetries(taskName)
  }
}];

function isCriticalError(error, task) {
  const criticalErrors = ['authentication_failed', 'database_connection_error', 'api_rate_exceeded'];
  const criticalTasks = ['system_health_check', 'alert_management'];
  return criticalErrors.some(e => error.includes(e)) || criticalTasks.includes(task);
}

function shouldRetryError(error, task) {
  const retryableErrors = ['timeout', 'temporary_failure', 'rate_limit'];
  return retryableErrors.some(e => error.includes(e)) && ($json.retry_count || 0) < getMaxRetries(task);
}

function getMaxRetries(task) {
  const retryConfig = {
    'system_health_check': 3,
    'alert_management': 2,
    'multi_source_ingestion': 3,
    'portfolio_analysis': 1,
    'ml_model_management': 2,
    'external_api_integration': 3,
    'data_cleanup': 1
  };
  return retryConfig[task] || 2;
}

